using XEngine.XUI;
using XEngine.XUI.Core;

/// <summary>
/// Business logic for the <c>LoginDemo</c> screen (UI/logindemo/LoginDemo.xui).
/// Reach controls through <c>View</c>; this class never touches a GameObject.
/// Generated by xui_scaffold, logic filled in as the M4/M5 PSD pipeline demo.
/// </summary>
[XuiScreen("LoginDemo")]
public partial class LoginDemo : XuiController<LoginDemoView>
{
    private const int MinNameLength = 3;

    /// <summary>Runs once. Subscribe here, not in OnShow.</summary>
    protected override void OnRegisterEvents()
    {
        View.BtnLogin.OnClick += OnLoginClicked;
    }

    /// <summary>Runs every time the screen becomes visible.</summary>
    protected override void OnShow(object? context)
    {
        View.TxtTitle.TextValue = "Account Login";
    }

    private void OnLoginClicked()
    {
        string name = View.InputUser.Text.Trim();
        if (name.Length < MinNameLength)
        {
            Xui.Toast("Username needs at least " + MinNameLength + " characters");
            return;
        }

        Xui.Toast("Welcome, " + name + "!");
        View.TxtTitle.TextValue = "Welcome, " + name;
    }
}
